{"command":"set -o pipefail
REPO='edburns/dd-3072680-cargotracker-non-devoxx-fixture'; OWNER='edburns'; NAME='dd-3072680-cargotracker-non-devoxx-fixture'; PR=11; ISSUE=6; BASE='experiment/shepherd-control'; EXPECTED_HEAD='4d9414f09e1071bd10afe29589dc7f300b4562e5'
PR_JSON=$(gh api "/repos/$REPO/pulls/$PR")
STATE=$(jq -r '.state' <<<"$PR_JSON"); DRAFT=$(jq -r '.draft' <<<"$PR_JSON"); ACTUAL_BASE=$(jq -r '.base.ref' <<<"$PR_JSON"); HEAD=$(jq -r '.head.sha' <<<"$PR_JSON"); BASE_SHA=$(jq -r '.base.sha' <<<"$PR_JSON"); CHANGED=$(jq -r '.changed_files' <<<"$PR_JSON"); HEAD_REF=$(jq -r '.head.ref' <<<"$PR_JSON")
[ "$STATE" = open ] && [ "$DRAFT" = true ] && [ "$ACTUAL_BASE" = "$BASE" ] && [ "$HEAD" = "$EXPECTED_HEAD" ] || { echo "PR_STATE_GATE=FAIL $STATE $DRAFT $ACTUAL_BASE $HEAD"; exit 2; }
LINKED=$(gh api graphql -f query='query($owner:String!,$name:String!,$number:Int!){repository(owner:$owner,name:$name){pullRequest(number:$number){closingIssuesReferences(first:100){nodes{number}}}}}' -F owner="$OWNER" -F name="$NAME" -F number="$PR" --jq ".data.repository.pullRequest.closingIssuesReferences.nodes[] | select(.number == $ISSUE) | .number")
[ "$LINKED" = "$ISSUE" ] || { echo 'LINK_GATE=FAIL'; exit 3; }
TIMELINE=$(gh api "/repos/$REPO/issues/$PR/timeline?per_page=100" -H 'Accept: application/vnd.github+json')
START=$(jq -r '[.[] | select(.event == "copilot_work_started") | .created_at] | max // empty' <<<"$TIMELINE"); FINISH=$(jq -r '[.[] | select(.event == "copilot_work_finished") | .created_at] | max // empty' <<<"$TIMELINE")
[ -n "$START" ] && [ -n "$FINISH" ] && [[ "$FINISH" > "$START" || "$FINISH" == "$START" ]] || { echo 'CCA_GATE=FAIL'; exit 4; }
FILES=$(gh api "/repos/$REPO/pulls/$PR/files?per_page=100" --paginate --jq '.[].filename'); FILE_COUNT=$(printf '%s\n' "$FILES" | sed '/^$/d' | wc -l)
BASE_TREE=$(gh api "/repos/$REPO/git/commits/$BASE_SHA" --jq '.tree.sha'); HEAD_TREE=$(gh api "/repos/$REPO/git/commits/$HEAD" --jq '.tree.sha')
[ "$CHANGED" -gt 0 ] && [ "$FILE_COUNT" -gt 0 ] && [ "$BASE_TREE" != "$HEAD_TREE" ] || { echo 'DIFF_GATE=FAIL'; exit 5; }
CHECKS=$(gh api "/repos/$REPO/commits/$HEAD/check-runs?per_page=100" --paginate --slurp)
PENDING=$(jq '[.[].check_runs[] | select(.status != "completed")] | length' <<<"$CHECKS"); FAILING=$(jq '[.[].check_runs[] | select(.status == "completed") | select(.conclusion != "success" and .conclusion != "skipped" and .conclusion != "neutral")] | length' <<<"$CHECKS"); RELEVANT=$(jq '[.[].check_runs[] | select(.name == "Shepherd task Cargo Tracker" and .status == "completed" and .conclusion == "success")] | length' <<<"$CHECKS")
[ "$PENDING" -eq 0 ] && [ "$FAILING" -eq 0 ] && [ "$RELEVANT" -gt 0 ] || { echo "CHECK_GATE=FAIL pending=$PENDING failing=$FAILING relevant=$RELEVANT"; exit 6; }
RUN_BLOCKERS=$(gh run list -R "$REPO" --branch "$HEAD_REF" --limit 100 --json headSha,status,conclusion --jq "[.[] | select(.headSha == \"$HEAD\") | select(.status != \"completed\" or .conclusion == \"action_required\")] | length")
[ "$RUN_BLOCKERS" -eq 0 ] || { echo "WORKFLOW_GATE=FAIL blockers=$RUN_BLOCKERS"; exit 7; }
REVIEW_STATE=$(gh api graphql --paginate -f query='query($owner:String!,$name:String!,$number:Int!,$endCursor:String){repository(owner:$owner,name:$name){pullRequest(number:$number){reviewDecision reviewThreads(first:100,after:$endCursor){nodes{isResolved comments(last:1){nodes{author{login} body url}}}pageInfo{hasNextPage endCursor}}}}}' -F owner="$OWNER" -F name="$NAME" -F number="$PR")
UNRESOLVED=$(jq -s '[.[].data.repository.pullRequest.reviewThreads.nodes[] | select(.isResolved == false)] | length' <<<"$REVIEW_STATE"); DECISION=$(jq -rs '[.[].data.repository.pullRequest.reviewDecision // empty] | last // empty' <<<"$REVIEW_STATE")
[ "$UNRESOLVED" -eq 0 ] && [ "$DECISION" != CHANGES_REQUESTED ] || { echo "REVIEW_GATE=FAIL unresolved=$UNRESOLVED decision=$DECISION"; exit 8; }
BOT_ISSUE_COMMENTS=$(gh pr view "$PR" -R "$REPO" --comments --json comments --jq '[.comments[] | select(.author.login | test("bot|copilot|agent"; "i"))] | length'); REVIEW_COMMENTS=$(gh api "/repos/$REPO/pulls/$PR/comments?per_page=100" --paginate --slurp | jq '[.[][]] | length')
[ "$BOT_ISSUE_COMMENTS" -eq 0 ] && [ "$REVIEW_COMMENTS" -eq 0 ] || { echo "COMMENT_GATE=FAIL bot=$BOT_ISSUE_COMMENTS review=$REVIEW_COMMENTS"; exit 9; }
BODY=$(jq -r '.body // ""' <<<"$PR_JSON")
for evidence in './mvnw clean package -Popenliberty liberty:run' '12/04/2026' '12/05/2026' 'stores data in memory' 'Liberty stopped cleanly'; do [[ "$BODY" == *"$evidence"* ]] || { echo "EVIDENCE_GATE=FAIL missing=$evidence"; exit 10; }; done
FINAL_HEAD=$(gh pr view "$PR" -R "$REPO" --json headRefOid --jq '.headRefOid'); [ "$FINAL_HEAD" = "$HEAD" ] || { echo "HEAD_STABILITY_GATE=FAIL $HEAD $FINAL_HEAD"; exit 11; }
printf 'PR_STATE_GATE=PASS\nLINK_GATE=PASS issue=%s\nCCA_GATE=PASS start=%s finish=%s\nDIFF_GATE=PASS files=%s changed=%s\nCHECK_GATE=PASS substantive=%s\nWORKFLOW_GATE=PASS\nREVIEW_GATE=PASS unresolved=%s decision=%s\nCOMMENT_GATE=PASS\nEVIDENCE_GATE=PASS\nHEAD_STABILITY_GATE=PASS head=%s\n' "$ISSUE" "$START" "$FINISH" "$FILE_COUNT" "$CHANGED" "$RELEVANT" "$UNRESOLVED" "${DECISION:-NONE}" "$HEAD"","description":"Run atomic final readiness gate","initial_wait":600,"mode":"sync"}
